import type { IncomingMessage } from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocket, WebSocketServer } from 'ws';
import { LiveCanvasError, type LiveCanvasService } from '../../../../application/mapping/agent/liveCanvasService';
import { liveCanvasMessageSchema, type LiveCanvasEvent } from '../../../../domain/mapping/agent/liveCanvasStatus';
import { sendJson } from '../../http/http';
import type { Connect } from 'vite';
import type { ServerResponse } from 'node:http';

export async function readShortContext(request: Connect.IncomingMessage, response: ServerResponse, url: URL, service: LiveCanvasService) {
  response.setHeader('cache-control', 'no-store');
  if (request.method !== 'GET') return sendJson(response, 405, { error: 'method not allowed' });
  const workspaceInstanceId = url.searchParams.get('workspaceInstanceId'), documentId = url.searchParams.get('documentId');
  if (!workspaceInstanceId || workspaceInstanceId.length > 200 || !documentId || documentId.length > 200
    || url.searchParams.getAll('workspaceInstanceId').length !== 1 || url.searchParams.getAll('documentId').length !== 1)
    return sendJson(response, 400, { code: 'INVALID_REQUEST', error: 'Provide one workspaceInstanceId and one documentId (1–200 characters each)' });
  try {
    const context = await service.shortContextForCanvas(workspaceInstanceId, documentId);
    response.setHeader('X-Canvas-Epoch', context.canvasEpoch);
    response.setHeader('X-Document-Version', String(context.version));
    return sendJson(response, 200, context);
  } catch (error) {
    if (error instanceof LiveCanvasError) return sendJson(response, error.status, { code: error.code, error: error.message });
    const message = error instanceof Error ? error.message : String(error);
    return sendJson(response, 503, { code: 'CONTEXT_UNAVAILABLE', error: message });
  }
}

export function readLiveSelection(request: Connect.IncomingMessage, response: ServerResponse, connectionId: string, service: LiveCanvasService) {
  response.setHeader('cache-control', 'private, no-cache');
  if (request.method !== 'GET') return sendJson(response, 405, { error: 'method not allowed' });
  try {
    const selection = service.read(connectionId);
    response.setHeader('X-Canvas-Epoch', selection.canvasEpoch);
    response.setHeader('X-Selection-Sequence', String(selection.sequence));
    response.setHeader('X-Document-Version', String(selection.documentVersion));
    response.setHeader('X-Selection-Received-At', selection.receivedAt);
    const etag = `"${selection.connectionId}:${selection.sequence}"`;
    response.setHeader('etag', etag);
    const matches = request.headers['if-none-match']?.split(',').some(tag => tag.trim().replace(/^W\//, '') === etag || tag.trim() === '*');
    if (matches) { response.statusCode = 304; response.end(); return; }
    sendJson(response, 200, selection);
  } catch (error) {
    if (!(error instanceof LiveCanvasError)) throw error;
    sendJson(response, error.status, { code: error.code, error: error.message });
  }
}

/** One endpoint; the first frame either attaches an external reader or registers a browser publisher. */
type UpgradeListener = (request: IncomingMessage, socket: Duplex, head: Buffer) => void;
interface UpgradeServer {
  on(event: 'upgrade', listener: UpgradeListener): unknown;
  off(event: 'upgrade', listener: UpgradeListener): unknown;
}

export function attachLiveCanvasSockets(server: UpgradeServer, service: LiveCanvasService, options: { agentContextUploadsEnabled?: boolean; canvasWritesEnabled?: boolean } = {}) {
  const sockets = new WebSocketServer({ noServer: true, maxPayload: 8 * 1024 * 1024, perMessageDeflate: false });
  const alive = new Set<WebSocket>();
  sockets.on('connection', ws => {
    alive.add(ws);
    let workspaceInstanceId: string | undefined, connectionId: string | undefined;
    let contextPending = false, attaching = false, contextAllowance = 0;
    const send = (event: LiveCanvasEvent) => {
      if (ws.readyState !== WebSocket.OPEN) return;
      // Deltas cannot be dropped/coalesced independently. Bound the transport queue
      // and force slow readers to reconnect for an authoritative snapshot instead.
      if (ws.bufferedAmount > 64 * 1024 + contextAllowance) { ws.close(1013, 'Reader too slow; reconnect for snapshot'); return; }
      const encoded = JSON.stringify(event);
      const hasContext = event.type === 'context.snapshot' || event.type === 'attached' && event.context !== undefined;
      if (hasContext) {
        const bytes = Buffer.byteLength(encoded);
        if (bytes > 64 * 1024 * 1024) { ws.close(1009, 'Canvas context exceeds 64 MiB transport limit'); return; }
        contextAllowance += bytes;
        ws.send(encoded, () => { contextAllowance -= bytes; });
      } else ws.send(encoded);
    };
    let handshake = setTimeout(() => { if (!connectionId && !workspaceInstanceId) ws.close(1008, 'Attach required'); }, 10_000);
    ws.on('pong', () => alive.add(ws));
    ws.on('error', () => ws.terminate());
    ws.on('message', async (raw, binary) => {
      let requestId: string | undefined;
      try {
        if (binary) throw new LiveCanvasError('INVALID_MESSAGE', 400, 'Expected a JSON text frame');
        const decoded: unknown = JSON.parse(raw.toString());
        if (decoded && typeof decoded === 'object' && 'requestId' in decoded
          && typeof decoded.requestId === 'string' && decoded.requestId.length <= 200) requestId = decoded.requestId;
        const message = liveCanvasMessageSchema.parse(decoded);
        if ((message.type === 'diagram.paste' || message.type === 'diagram.copy') && options.canvasWritesEnabled !== true)
          throw new LiveCanvasError('HTTP_WRITES_DISABLED', 403, 'Canvas writes are disabled; start the server with --http to enable them.');
        if (options.agentContextUploadsEnabled !== true && message.type === 'agent-context.upload') {
          throw new LiveCanvasError('HTTP_WRITES_DISABLED', 403, 'Agent context uploads are disabled; start the server with --http to enable them.');
        }
        if (message.type === 'attach' || message.type === 'publish') {
          if (connectionId || workspaceInstanceId || attaching) throw new LiveCanvasError('ALREADY_ATTACHED', 409, 'Open another socket to bind another canvas');
          if (message.type === 'attach') {
            attaching = true;
            let context;
            try {
              if (message.includeContext) {
                clearTimeout(handshake);
                handshake = setTimeout(() => ws.close(1008, 'Canvas context timed out'), 30_000);
                context = await service.contextForCanvas(message.workspaceInstanceId, message.documentId);
              }
            } finally { attaching = false; }
            if (ws.readyState !== WebSocket.OPEN) return;
            const initial = service.attach(message.workspaceInstanceId, message.documentId, send);
            connectionId = initial.connectionId;
            send({ type: 'attached', ...initial, ...(context ? { context } : {}) });
          } else {
            service.publish(ws, message.workspaceInstanceId, send, message.capabilities);
            workspaceInstanceId = message.workspaceInstanceId;
            send({ type: 'publisher.ready', protocolVersion: 2 });
          }
          clearTimeout(handshake);
        } else if (message.type === 'diagram.copy') {
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          send(await service.copy(connectionId, message));
        } else if (message.type === 'diagram.copy.reply') {
          if (!workspaceInstanceId) throw new LiveCanvasError('PUBLISHER_REQUIRED', 403);
          service.copyReply(ws, workspaceInstanceId, message);
        } else if (message.type === 'diagram.paste') {
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          send(await service.paste(connectionId, message));
        } else if (message.type === 'diagram.paste.reply') {
          if (!workspaceInstanceId) throw new LiveCanvasError('PUBLISHER_REQUIRED', 403);
          service.pasteReply(ws, workspaceInstanceId, message);
        } else if (message.type === 'agent-context.upload') {
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          const { type: _, requestId: uploadRequestId, ...trajectory } = message;
          send({ type: 'agent-context.uploaded', requestId: uploadRequestId, connectionId,
            ...service.uploadAgentContext(connectionId, uploadRequestId, trajectory) });
        } else if (message.type === 'context.get') {
          requestId = message.requestId;
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          if (contextPending || contextAllowance > 0) throw new LiveCanvasError('CONTEXT_BUSY', 409, 'Wait for the pending context request');
          contextPending = true;
          try { send({ type: 'context.snapshot', requestId, ...await service.context(connectionId) }); }
          finally { contextPending = false; }
        } else {
          if (!workspaceInstanceId) throw new LiveCanvasError('PUBLISHER_REQUIRED', 403);
          if (message.type === 'remove') service.remove(ws, workspaceInstanceId, message.documentId, message.canvasEpoch);
          else {
            const { type: _, ...selection } = message;
            service.update(ws, workspaceInstanceId, selection);
          }
        }
      } catch (error) {
        send({ type: 'error', ...(requestId ? { requestId } : {}), code: error instanceof LiveCanvasError || error instanceof AgentContextError ? error.code : 'INVALID_MESSAGE',
          error: error instanceof Error ? error.message : String(error) });
      }
    });
    ws.on('close', () => {
      clearTimeout(handshake); alive.delete(ws);
      if (connectionId) service.detach(connectionId);
      if (workspaceInstanceId) service.disconnect(ws, workspaceInstanceId);
    });
  });
  const upgrade: UpgradeListener = (request, socket, head) => {
    if (new URL(request.url ?? '/', 'http://localhost').pathname !== '/api/mapping/live') return;
    // Native clients may omit Origin. Browser clients must belong to this app's origin.
    let allowed = !request.headers.origin;
    try { allowed ||= new URL(request.headers.origin!).host === request.headers.host; } catch { /* invalid origin */ }
    if (!allowed || sockets.clients.size >= 1024) {
      socket.end(`HTTP/1.1 ${allowed ? '503 Service Unavailable' : '403 Forbidden'}\r\nConnection: close\r\n\r\n`); return;
    }
    sockets.handleUpgrade(request, socket, head, ws => sockets.emit('connection', ws, request));
  };
  server.on('upgrade', upgrade);
  const heartbeat = setInterval(() => {
    for (const ws of sockets.clients) {
      if (!alive.delete(ws)) ws.terminate(); else ws.ping();
    }
  }, 15_000);
  heartbeat.unref();
  return () => {
    clearInterval(heartbeat); server.off('upgrade', upgrade);
    for (const ws of sockets.clients) ws.terminate();
    sockets.close();
  };
}
"},{"path":"src/server/routes/mapping/agent-chat/agentChatRoutes.ts","text":"import { chatCanvasTargetSchema } from '../../../../../domain/mapping/agent-chat/agentChat';
import type { ServerResponse } from 'node:http';
import type { Connect } from 'vite';
import type { AgentChatService } from '../../../../../application/mapping/agent-chat/agentChatService';
import { findChatItem, type ChatEvent, type ChatItem } from '../../../../../domain/mapping/agent-chat/agentChat';
import { readBody, sendJson } from '../../../http/http';

function publicGeneration(generation: import('../../../../../domain/mapping/agent-chat/agentChat').ChatGeneration) {
  const { history: _, ...visible } = generation;
  return visible;
}
function publicSession(session: import('../../../../../domain/mapping/agent-chat/agentChat').ChatSession) {
  const { toolDefinitions: _, generationRequests: __, ...visible } = session;
  return { ...visible, ...(session.generation ? { generation: publicGeneration(session.generation) } : {}) };
}
function publicEvent(event: ChatEvent): ChatEvent {
  if (event.type === 'snapshot') return { ...event, session: publicSession(event.session) };
  if (event.type === 'state' && event.patch.generation) return { ...event, patch: { ...event.patch, generation: publicGeneration(event.patch.generation) } };
  if (event.type === 'batch') return { ...event, events: event.events.map(item => publicEvent(item) as typeof item) };
  return event;
}

function snapshotItem(item: ChatItem): ChatItem {
  if (item.kind !== 'tool' || item.status === 'inProgress') return item;
  if (item.text.length <= 1000 && !item.changes?.some(change => change.diff.length > 1000)) return item;
  return { ...item, detailAvailable: true, text: item.text.trimEnd().split('\n').slice(-3).map(line => line.slice(0, 240)).join('\n'),
    changes: item.changes?.map(change => ({ ...change, diff: change.diff.split('\n').slice(0, 3).map(line => line.slice(0, 240)).join('\n') })) };
}

export async function handleAgentChat(request: Connect.IncomingMessage, response: ServerResponse, url: URL, chat: AgentChatService) {
  // Use the actual listening socket, not caller-controlled Host/forwarded headers.
  if (request.socket.localPort) chat.setMcpOrigin(`http://127.0.0.1:${request.socket.localPort}`);
  const route = url.pathname.slice('/api/mapping/agent-chat'.length);
  const binding = typeof request.headers['x-canvas-chat-binding'] === 'string' ? request.headers['x-canvas-chat-binding'] : '';
  if (route === '/tools' && request.method === 'GET') return sendJson(response, 200, await chat.toolDefinitions(binding));
  const tool = route.match(/^\/tools\/([A-Za-z0-9_-]+)$/);
  if (tool && request.method === 'POST') {
    const body = await readBody(request) as { input?: unknown; callId?: unknown };
    if (typeof body.callId !== 'string' || !body.callId || body.callId.length > 200)
      return sendJson(response, 400, { error: 'A tool call ID is required.' });
    return sendJson(response, 200, await chat.callBoundTool(binding, tool[1], body.input, body.callId));
  }
  if (route === '/generations' && request.method === 'GET') return sendJson(response, 200, await chat.generations(chatCanvasTargetSchema.parse({
    workspaceInstanceId: url.searchParams.get('workspaceInstanceId'), documentId: url.searchParams.get('documentId') })));
  if (route === '/info' && request.method === 'GET') return sendJson(response, 200, await chat.info());
  if (route === '/sessions/resume' && request.method === 'POST') return sendJson(response, 200, publicSession(await chat.resume(await readBody(request))));
  if (route === '/sessions') {
    if (request.method === 'GET') return sendJson(response, 200, await chat.list());
    if (request.method === 'POST') return sendJson(response, 200, publicSession(await chat.create(await readBody(request))));
  }
  const match = route.match(/^\/sessions\/([a-f0-9-]+)(?:\/(events|send|read-canvas|reload-tools|interrupt|answer|items|gen-alternatives|cancel-generation)(?:\/([^/]+))?)?$/);
  if (!match) return sendJson(response, 404, { error: 'Chat route not found' });
  const [, id, action, requestId] = match;
  if (request.method === 'GET' && !action) return sendJson(response, 200, publicSession(await chat.get(id)));
  if (request.method === 'GET' && action === 'items' && requestId) {
    const item = findChatItem(await chat.get(id), decodeURIComponent(requestId));
    return sendJson(response, item ? 200 : 404, item ?? { error: 'Chat activity not found' });
  }
  if (request.method === 'GET' && action === 'events') {
    await chat.get(id);
    if (response.destroyed) return;
    // Preview's compression middleware does not honor no-transform. Explicit identity
    // prevents gzip from holding the final records of a long-lived event stream.
    response.writeHead(200, { 'Content-Type': 'text/event-stream', 'Content-Encoding': 'identity', 'Cache-Control': 'no-cache, no-transform', Connection: 'keep-alive', 'X-Accel-Buffering': 'no' });
    response.flushHeaders();
    let unsubscribe = () => {};
    let snapshotAllowance = 0;
    response.on('drain', () => { snapshotAllowance = 0; });
    const heartbeat = setInterval(() => { response.write(': heartbeat\n\n'); }, 15_000);
    response.once('close', () => { clearInterval(heartbeat); unsubscribe(); });
    const writeEvent = (event: ChatEvent, snapshot = false) => {
      if (response.destroyed) return;
      const data = `data: ${JSON.stringify(event)}\n\n`;
      // A valid retained-history snapshot can exceed the live-event backlog limit.
      // Allow that single snapshot to drain; still bound additional queued events.
      // Otherwise large histories reconnect forever without ever receiving their snapshot.
      if (snapshot) snapshotAllowance += Buffer.byteLength(data);
      if (response.write(data)) snapshotAllowance = 0;
      else if (response.writableLength > snapshotAllowance + 2 * 1024 * 1024) response.destroy();
    };
    unsubscribe = await chat.subscribe(id, incoming => {
      const event = publicEvent(incoming);
      if (event.type !== 'snapshot') { writeEvent(event); return; }
      // Keep SSE records small. The client assembles parts before publishing once,
      // so reconnect never renders an incomplete transcript or parses a multi-MB line.
      const items = event.session.items.map(snapshotItem);
      if (items.length <= 1) { writeEvent({ ...event, session: { ...event.session, items } }, true); return; }
      writeEvent({ type: 'snapshot', session: { ...event.session, items: [] }, partial: true }, true);
      for (let start = 0; start < items.length && !response.destroyed; start++)
        writeEvent({ type: 'snapshot-part', items: [items[start]], final: start + 1 >= items.length }, true);
    });
    if (response.destroyed) { clearInterval(heartbeat); unsubscribe(); }
    return;
  }
  if (request.method === 'POST') {
    if (action === 'gen-alternatives') {
      const { canvas, ...input } = await readBody(request) as Record<string, unknown>;
      return sendJson(response, 200, await chat.genAlternatives(id, input, chatCanvasTargetSchema.parse(canvas)));
    }
    if (action === 'cancel-generation') await chat.cancelGeneration(id);
    else if (action === 'send') await chat.send(id, await readBody(request));
    else if (action === 'read-canvas') await chat.readCanvas(id, await readBody(request));
    else if (action === 'reload-tools') await chat.reloadTools(id);
    else if (action === 'interrupt') await chat.interrupt(id);
    else if (action === 'answer' && requestId) await chat.answer(id, requestId, await readBody(request));
    else return sendJson(response, 404, { error: 'Chat action not found' });
    return sendJson(response, 200, { ok: true });
  }
  return sendJson(response, 405, { error: 'method not allowed' });
}
"},{"path":"src/server/routes/mapping/evals/evalRoutes.ts","text":"import { z } from 'zod';
import type { ServerResponse } from 'node:http';
import type { Connect } from 'vite';
import type { EvalPromptService } from '../../../../../application/mapping/evals/evalPromptService';
import type { EvalRunService } from '../../../../../application/mapping/evals/evalRunService';
import type { EvalReferenceService } from '../../../../../application/mapping/evals/evalReferenceService';
import { captureCanvasSchema } from '../../../../../domain/mapping/evals/evalReference';
import { archiveEvalPromptSchema } from '../../../../../domain/mapping/evals/evalPrompt';
import { renameEvalRunSchema, summarizeEvalRun } from '../../../../../domain/mapping/evals/evalRun';
import { readBody, sendJson } from '../../../http/http';

const segment = '([A-Za-z0-9][A-Za-z0-9_-]{0,80})';
export async function handleEvalRoutes(request: Connect.IncomingMessage, response: ServerResponse, url: URL, prompts: EvalPromptService, runs: EvalRunService, references: EvalReferenceService) {
  const route = url.pathname.slice('/api/mapping/evals'.length), method = request.method;
  const historyMatch = route.match(new RegExp(`^/histories/${segment}$`));
  if (historyMatch && method === 'GET' && runs.histories) {
    const timeline = await runs.histories.read(historyMatch[1]);
    const { documents: _, ...summary } = timeline;
    return sendJson(response, 200, summary);
  }
  if (route === '/experiments' && runs.experiments) {
    if (method === 'GET') return sendJson(response, 200, await runs.experiments.list());
    if (method === 'POST') return sendJson(response, 200, await runs.experiments.save(await readBody(request)));
  }
  const experimentMatch = route.match(new RegExp(`^/experiments/${segment}$`));
  if (experimentMatch && method === 'GET' && runs.experiments) return sendJson(response, 200, await runs.experiments.read(experimentMatch[1]));
  const approveMatch = route.match(new RegExp(`^/experiments/${segment}/approve$`));
  if (approveMatch && method === 'POST' && runs.experiments) return sendJson(response, 202, await runs.experiments.approve(approveMatch[1], await readBody(request)));
  const judgeMatch = route.match(new RegExp(`^/experiments/${segment}/judge$`));
  if (judgeMatch && method === 'POST' && runs.experiments) return sendJson(response, 200, await runs.experiments.judge(judgeMatch[1], await readBody(request)));
  const relaunchMatch = route.match(new RegExp(`^/experiments/${segment}/relaunch$`));
  if (relaunchMatch && method === 'POST' && runs.experiments) return sendJson(response, 202, await runs.experiments.relaunch(relaunchMatch[1], await readBody(request)));
  if (route === '/judgements' && method === 'GET') return sendJson(response, 200, await runs.judgements?.list(url.searchParams.get('runId') ?? undefined) ?? []);
  const judgementMatch = route.match(new RegExp(`^/judgements/${segment}$`));
  if (judgementMatch && runs.judgements) {
    if (method === 'GET') return sendJson(response, 200, await runs.judgements.read(judgementMatch[1]));
    if (method === 'DELETE') { await runs.judgements.delete(judgementMatch[1]); return sendJson(response, 200, { deleted: true }); }
  }
  if (route === '/references') {
    if (method === 'GET') return sendJson(response, 200, await references.list(url.searchParams.get('archived') === 'true'));
    if (method === 'POST') return sendJson(response, 200, await references.create(await readBody(request)));
  }
  const referenceMatch = route.match(new RegExp(`^/references/${segment}$`));
  if (referenceMatch && method === 'GET') return sendJson(response, 200, await references.read(referenceMatch[1]));
  if (referenceMatch && method === 'PATCH') return sendJson(response, 200, await references.update(referenceMatch[1], await readBody(request)));
  if (route === '/reference-groups') {
    if (method === 'GET') return sendJson(response, 200, await references.listGroups());
    if (method === 'POST') return sendJson(response, 200, await references.createGroup(await readBody(request)));
  }
  const referenceGroupMatch = route.match(new RegExp(`^/reference-groups/${segment}$`));
  if (referenceGroupMatch && method === 'PATCH') return sendJson(response, 200, await references.updateGroup(referenceGroupMatch[1], await readBody(request)));
  if (referenceGroupMatch && method === 'DELETE') { await references.deleteGroup(referenceGroupMatch[1]); return sendJson(response, 200, { deleted: true }); }
  if (route === '/reference-sessions' && method === 'POST' && runs.referenceGenerations) return sendJson(response, 200, await runs.referenceGenerations.open(await readBody(request)));
  const referenceSessionMatch = route.match(new RegExp(`^/reference-sessions/${segment}/generate$`));
  if (referenceSessionMatch && method === 'POST' && runs.referenceGenerations) return sendJson(response, 202, await runs.referenceGenerations.generate(referenceSessionMatch[1], await readBody(request)));
  const referenceSourcesMatch = route.match(new RegExp(`^/reference-sessions/${segment}/load-sources$`));
  if (referenceSourcesMatch && method === 'POST' && runs.referenceGenerations) return sendJson(response, 202, await runs.referenceGenerations.loadSources(referenceSourcesMatch[1], await readBody(request)));
  if (route === '/capture' && method === 'POST') return sendJson(response, 200, await runs.captureCanvas(captureCanvasSchema.parse(await readBody(request)).source));
  if (route.startsWith('/layout-templates') && runs.layoutTemplates) {
    const templates = runs.layoutTemplates;
    if (route === '/layout-templates' && method === 'GET') return sendJson(response, 200, await templates.list());
    if (route === '/layout-templates' && method === 'POST') return sendJson(response, 200, await templates.save(await readBody(request)));
    if (route === '/layout-templates/capture' && method === 'POST') return sendJson(response, 200, await templates.capture(await readBody(request)));
    const match = route.match(new RegExp(`^/layout-templates/${segment}$`));
    if (match && method === 'POST') return sendJson(response, 200, await templates.update(match[1], await readBody(request)));
    if (match && method === 'DELETE') { await templates.delete(match[1]); return sendJson(response, 200, { deleted: true }); }
  }
  const snapshotMatch = route.match(new RegExp(`^/prompt-snapshots/${segment}$`));
  if (snapshotMatch && method === 'GET') return sendJson(response, 200, await prompts.readSnapshot(snapshotMatch[1]));
  if (route === '/prompt-snapshots' && method === 'GET') return sendJson(response, 200, await prompts.listSnapshots());
  if (route === '/prompt-snapshots' && method === 'POST') {
    const input = z.object({ requestId: z.string().uuid(), name: z.string().min(1).max(120) }).strict().parse(await readBody(request));
    return sendJson(response, 200, await prompts.snapshot(input.requestId, input.name));
  }
  const forkMatch = route.match(new RegExp(`^/prompts/${segment}/fork$`));
  if (forkMatch && method === 'POST') {
    const input = z.object({ requestId: z.string().uuid(), version: z.number().int().positive(), name: z.string().min(1).max(120) }).strict().parse(await readBody(request));
    return sendJson(response, 200, await prompts.fork(forkMatch[1], input.version, input.requestId, input.name));
  }
  if (route === '/prompts') {
    if (method === 'GET') return sendJson(response, 200, await prompts.list());
    if (method === 'POST') return sendJson(response, 200, await prompts.save(await readBody(request)));
  }
  let match = route.match(new RegExp(`^/prompts/${segment}$`));
  if (match && method === 'GET') return sendJson(response, 200, await prompts.read(match[1]));
  match = route.match(new RegExp(`^/prompts/${segment}/lineage$`));
  if (match && method === 'POST') return sendJson(response, 200, await prompts.trackLineage(match[1], await readBody(request)));
  match = route.match(new RegExp(`^/prompts/${segment}/archive$`));
  if (match && method === 'POST') return sendJson(response, 200, await prompts.setArchived(match[1], archiveEvalPromptSchema.parse(await readBody(request)).archived));
  if (route === '/roll-ups' && method === 'POST') return sendJson(response, 202, await runs.startRollUp(await readBody(request)));
  if (route === '/runs') {
    if (method === 'GET') return sendJson(response, 200, await runs.list());
    if (method === 'POST') return sendJson(response, 202, await runs.start(await readBody(request)));
  }
  if (route === '/runs/delete' && method === 'POST') {
    const input = z.object({ ids: z.array(z.string().regex(/^[A-Za-z0-9][A-Za-z0-9_-]{0,80}$/)).min(1) }).strict().parse(await readBody(request));
    await runs.deleteRuns(input.ids); return sendJson(response, 200, { deleted: true });
  }
  if (route === '/promotion-targets' && method === 'GET') return sendJson(response, 200, await runs.promotionTargets());
  const placementBackfillMatch = route.match(new RegExp(`^/runs/${segment}/placement-backfill$`));
  if (placementBackfillMatch && method === 'POST') return sendJson(response, 200, await runs.backfillPlacementTracking(placementBackfillMatch[1], await readBody(request)));
  const promoteMatch = route.match(new RegExp(`^/runs/${segment}/promote$`));
  if (promoteMatch && method === 'POST') return sendJson(response, 200, await runs.promoteOutput(promoteMatch[1], await readBody(request)));
  const sourceMatch = route.match(new RegExp(`^/runs/${segment}/promotion-source$`));
  if (sourceMatch && method === 'GET') return sendJson(response, 200, await runs.promotionSource(sourceMatch[1], url.searchParams.get('cell') ?? ''));
  const resultMatch = route.match(new RegExp(`^/runs/${segment}/output-result$`));
  if (resultMatch && method === 'GET') return sendJson(response, 200, await runs.outputResult(resultMatch[1], url.searchParams.get('cell') ?? ''));
  if (resultMatch && method === 'POST') {
    const input = z.object({ cellKey: z.string().min(1).max(300), changeSessionId: z.string().min(1).max(200),
      expectedVersion: z.number().int().nonnegative() }).strict().parse(await readBody(request));
    return sendJson(response, 200, await runs.captureOutputResult(resultMatch[1], input));
  }
  match = route.match(new RegExp(`^/runs/${segment}$`));
  if (match && method === 'GET') {
    const summary = summarizeEvalRun(await runs.read(match[1]));
    const judgements = await runs.judgements?.list(summary.id) ?? [];
    return sendJson(response, 200, { ...summary, ...(judgements.length ? { judgements } : {}) });
  }
  if (match && method === 'DELETE') { await runs.deleteRun(match[1]); return sendJson(response, 200, { deleted: true }); }
  match = route.match(new RegExp(`^/runs/${segment}/rerun-chat$`));
  if (match && method === 'POST') { const input = z.object({ requestId: z.string().min(1).max(200) }).strict().parse(await readBody(request));
    return sendJson(response, 202, await runs.rerunLegacy(match[1], input.requestId)); }
  match = route.match(new RegExp(`^/runs/${segment}/rename$`));
  if (match && method === 'POST') return sendJson(response, 200, await runs.rename(match[1], renameEvalRunSchema.parse(await readBody(request)).name));
  match = route.match(new RegExp(`^/runs/${segment}/cancel$`));
  if (match && method === 'POST') { await runs.cancel(match[1]); return sendJson(response, 202, { cancelled: true }); }
  if (route === '/contexts' && method === 'GET') return sendJson(response, 200, await runs.listContexts(url.searchParams.get('query') ?? '', Number(url.searchParams.get('offset') ?? 0)));
  if (route === '/canvases' && method === 'GET') return sendJson(response, 200, await runs.generated());
  match = route.match(new RegExp(`^/canvases/${segment}$`));
  if (match && method === 'GET') return sendJson(response, 200, await runs.canvas(match[1], url.searchParams.get('checkpoint') ?? undefined));
  if (match && method === 'DELETE') { await runs.deleteCanvas(match[1]); return sendJson(response, 200, { deleted: true }); }
  match = route.match(new RegExp(`^/contexts/${segment}/outputs$`));
  if (match && method === 'DELETE') {
    const workflow = url.searchParams.get('workflow');
    if (workflow !== 'roll-up' && workflow !== 'alternatives' && workflow !== 'few-shot-refinement' && workflow !== 'diagram-change-proposal') return sendJson(response, 400, { error: 'Choose a workflow.' });
    await runs.deleteContextOutputs(match[1], workflow); return sendJson(response, 200, { deleted: true });
  }
  if (route === '/migrate' && method === 'POST') return sendJson(response, 200, await runs.migrate());
  return sendJson(response, 404, { error: 'Evals route not found' });
}

/** Mapping's Canvas tab only lists generated canvases and links to Evals. */
export async function handleGeneratedCanvasRoutes(request: Connect.IncomingMessage, response: ServerResponse, url: URL, runs: EvalRunService) {
  const route = url.pathname.slice('/api/mapping/generated-canvases'.length);
  if (request.method === 'GET' && !route) return sendJson(response, 200, await runs.generated());
  if (request.method === 'POST' && route === '/migrate') return sendJson(response, 200, await runs.migrate());
  return sendJson(response, 404, { error: 'Generated canvas route not found' });
}
